from h import *
P='bio'
# ================= 트립토판 오페론 (학원 학습지) =================
U='트립토판 오페론'
M('b2t01',P,U,1,'오페론의 종류를 바르게 짝지은 것은?',
 [('유도성 오페론 – lac 오페론, 억제성 오페론 – trp 오페론','유도성: 필요할 때 유도 / 억제성: 최종 산물이 많을 때 억제'),('유도성 오페론 – trp 오페론','trp는 평상시 켜져 있다가 꺼지는 억제성이에요.'),('억제성 오페론 – lac 오페론','lac은 젖당이 있을 때 켜지는 유도성이에요.'),('두 오페론 모두 유도성이다','trp는 억제성이에요.')],'억제성 = 평상시 전사 ON → 너무 많으면 억제 (항상 일정량 유지)',['b2:2'])
T('b2t02',P,U,1,'트립토판 오페론의 구조를 순서대로 쓴 약자는? (학습지 표기, 띄어쓰기 없이)',['POLAS','POLA S','P O L A S'],'P(프로모터) O(작동자) L(선도 서열) A(감쇠자, attenuator) S(구조 유전자 trpE·D·C·B·A)',['b2:2'])
M('b2t03',P,U,2,'lac 오페론과 trp 오페론의 조절 방식 비교로 옳은 것은?',
 [('trp 오페론에는 양의 조절이 없고, 트립토판이 억제자를 활성화하는 음의 조절이 있다','표의 내용 그대로예요.'),('trp 오페론도 포도당이 고갈되면 cAMP–CRP가 전사를 촉진한다','trp에는 양의 조절이 없어요.'),('lac 오페론에서는 알로젖당이 억제자를 활성화한다','알로젖당은 억제자를 불활성화(억제)해요.'),('trp 오페론에서 트립토판은 억제자를 불활성화한다','트립토판은 보조억제자로 억제자를 활성화해요.')],'',['b2:2','b2:1'])
E('b2t04',P,U,'[trp 연습 1-①] 트립토판 오페론의 전사 개시에 대한 음의 조절 기작을 설명하시오. [3점]',
 ['trpR이 만든 억제자는 평상시 불활성','트립토판 농도↑ → 트립토판(보조억제자)이 억제자에 결합 → 활성화','활성 억제자가 작동자에 결합 → RNA 중합 효소 결합 방해 → 전사 OFF'],
 '조절 유전자 trpR에서 만든 억제자는 그 자체로는 불활성이다. 트립토판 농도가 높으면 트립토판이 보조억제자로 억제자에 결합해 활성화시키고, 활성화된 억제자가 작동자에 결합하여 RNA 중합 효소의 전사를 막는다.',['b2:3'])
E('b2t05',P,U,'[trp 연습 1-②] 선도 유전자 전사체(mRNA)의 2차 구조가 구조 유전자의 전사와 전사 억제에 관여하는 기작(어테뉴에이션)을 설명하시오. [5점]',
 ['선도 펩티드 1 영역에 Trp 코돈 2개(연속)','[Trp]↑: 리보솜이 1을 빨리 지나 2를 덮음 → 3·4 헤어핀(종결자) + poly U → 전사 종결','[Trp]↓: 리보솜이 Trp 코돈에서 멈춤(1에서 정지) → 2·3 헤어핀(항종결자) → 3·4 형성 X → 전사 계속','원핵세포에서 전사·번역이 동시에 일어나 가능'],
 '선도 서열 1 영역에는 트립토판 코돈이 연속으로 있다. 트립토판이 많으면 리보솜이 1을 빠르게 번역하고 2를 덮어 3·4 헤어핀(전사 종결자)과 뒤의 U 서열이 만들어져 전사가 조기 종결된다. 트립토판이 부족하면 리보솜이 Trp 코돈에서 멈추어 2·3 헤어핀(항종결자)이 형성되므로 3·4 종결자가 생기지 못해 구조 유전자까지 전사된다.',['b2:2','b2:3'])
E('b2t06',P,U,'[trp 연습 1-③] 전사 감쇠가 원핵세포에서만 가능한 이유를 상세히 설명하시오. [3점]',
 ['원핵세포는 핵막이 없음','전사와 번역이 세포질에서 동시에 일어남','전사 중인 mRNA에 리보솜이 붙어 번역 속도가 mRNA 2차 구조(종결 여부)를 결정','진핵세포는 핵에서 전사 → 세포질에서 번역 (공간·시간 분리)'],
 '원핵세포는 핵막이 없어 전사가 진행되는 동안 mRNA에 리보솜이 붙어 번역이 동시에 일어난다. 감쇠는 리보솜의 번역 속도가 아직 전사 중인 선도 mRNA의 2차 구조를 결정하는 방식이므로, 전사(핵)와 번역(세포질)이 분리된 진핵세포에서는 불가능하다.',['b2:3'])
M('b2t07',P,U,2,'[trp 연습 1-④] trp 오페론의 조절에 cAMP–CRP가 필요 없는 이유로 가장 적절한 것은?',
 [('trp 오페론은 억제성 오페론으로 양의 조절을 받지 않기 때문','포도당 유무와 관계없이 트립토판 양으로만 조절돼요.'),('트립토판이 cAMP를 분해하기 때문','관계없어요.'),('trp 오페론에는 프로모터가 없기 때문','프로모터가 있어요(POLAS의 P).'),('trp 오페론은 진핵생물에 있기 때문','대장균의 오페론이에요.')],'',['b2:3'])
M('b2t08',P,U,2,'[trp 연습 2-①] trpR에 돌연변이가 생겨 억제자가 만들어지지 않을 때 예상되는 결과는?',
 [('트립토판이 많아도 전사 개시는 억제되지 않지만, 감쇠에 의한 조절은 여전히 일어난다','억제자 X → 음의 조절 X, 단 감쇠는 선도 서열이 하는 일이라 가능'),('트립토판이 있든 없든 전사가 완전히 멈춘다','억제자가 없으면 오히려 켜져요.'),('감쇠도 일어나지 않아 발현량이 항상 최대이다','감쇠는 trpL에 의존해요.'),('트립토판이 없을 때만 전사가 억제된다','반대예요.')],'',['b2:4'])
T('b2t09',P,U,2,'[trp 연습 2-②] 3·4 헤어핀 뒤에 U가 연속된 trp 선도 서열의 전사 종결은 RHO 의존성인가, RHO 비의존성인가?',['RHO비의존','RHO 비의존','Rho 비의존','rho-independent','비의존','비의존성','RHO 비의존성'],'GC가 많은 헤어핀 + poly U → RHO 단백질 없이 스스로 종결(내재적 종결)',['b2:4'])
M('b2t10',P,U,3,'[trp 연습 2-③④ 변형] trpL의 트립토판 코돈을 결실시키거나, 리보솜이 2 영역에 머물게 조절한 경우에 대한 설명으로 옳은 것은?',
 [('어느 경우든 종결은 3·4 헤어핀 + poly U에 의한 RHO 비의존성 종결이다','종결 방식 자체는 바뀌지 않아요.'),('Trp 코돈을 결실시키면 RHO 의존성 종결로 바뀐다','RHO 인자와 무관해요.'),('리보솜이 2 영역에 머물면 2·3 헤어핀이 형성된다','2를 덮으면 3·4가 생겨 종결돼요.'),('Trp 코돈을 결실시키면 트립토판이 없어도 항상 전사가 끝까지 진행된다','멈출 Trp 코돈이 없어 리보솜이 2까지 가서 3·4 형성 → 종결돼요.')],'',['b2:4'])
S('b2t11',P,U,3,'[trp 연습 3] 야생형과 돌연변이 대장균에서 트립토판 유무에 따른 TrpB 발현량을 조사했다. 야생형: 있음 1, 없음 150 / trpR⁻: 있음 50, 없음 ? / trpL⁻: 있음 ㉠, 없음 ?, 억제 효과 50배 / trpR⁻trpL⁻: 150, 150 (trpR⁻: 억제자 기능 상실, trpL⁻: 전사 종결 신호 기능 상실) [7점]',
 [pn('야생형의 전체 억제 효과는 몇 배인가?',150,0.5,'배',1,'150 / 1'),
  pn('trpR⁻에서 트립토판이 없을 때 발현량은?',150,0.5,'',1,'억제·감쇠 모두 없음 → 150'),
  pn('㉠에 적합한 값은?',3,0.01,'',3,'억제 효과 50배 → 150 / 50 = 3'),
  pn('전사 감쇠를 통한 트립토판의 억제 효과는 몇 배인가?',3,0.01,'배',2,'trpR⁻(억제자 X, 감쇠만): 150 / 50 = 3배 → 전체 150 = 억제자 50 × 감쇠 3')],['b2:4'])
# ================= 젖당 오페론 (학원 학습지·김나리T) =================
U='젖당 오페론'
T('b2l01',P,U,1,'젖당 오페론의 구조를 나타내는 학습지의 약자는? (띄어쓰기 없이)',['POS','P O S'],'P(프로모터) O(작동자) S(구조 유전자 lacZ·Y·A)',['b2:1'])
M('b2l02',P,U,1,'[꼭 숙지할 것] 젖당 오페론에 대한 설명으로 옳지 않은 것은?',
 [('조절 유전자 lacI는 젖당이 있을 때만 발현된다','조절 유전자는 존재한다면 항상 발현돼요(옳지 않음).'),('포도당이 고갈되면 cAMP–CAP에 의해 전사가 촉진된다','양의 조절'),('젖당이 유입되면 억제자가 억제되어 전사가 유도된다','음의 조절 해제'),('젖당 오페론은 on/off가 아니라 more/less이다','소량은 항상 발현돼요.')],'',['b2:5'])
M('b2l03',P,U,2,'젖당 오페론이 on/off가 아니라 more/less인 이유로 옳은 것은?',
 [('억제자가 결합해도 소량의 전사가 일어나 투과효소와 β-갈락토시데이스가 항상 약간 있어 젖당이 들어오면 알로젖당을 만들 수 있기 때문','젖당 → 알로젖당은 β-갈락토시데이스가 만들어요.'),('억제자가 작동자에 영원히 결합하기 때문','결합–해리를 반복해요.'),('cAMP가 항상 일정하기 때문','포도당에 따라 변해요.'),('lacZ가 프로모터 앞에 있기 때문','구조가 틀려요.')],'',['b2:8'])
M('b2l04',P,U,2,'젖당 오페론의 실제 유도체와 실험에서 쓰는 대체 유도체를 바르게 짝지은 것은?',
 [('알로젖당(1,6-결합) – IPTG','IPTG는 β-갈락토시데이스에 분해되지 않아 농도가 유지돼요.'),('젖당(1,4-결합) – X-gal','X-gal은 기질(발색)이에요.'),('포도당 – cAMP','관계없어요.'),('갈락토스 – IPTG','유도체는 알로젖당이에요.')],'젖당은 β1-4, 알로젖당은 β1-6 결합',['b2:1','b2:8'])
S('b2l05',P,U,2,'[정리 3] 젖당 오페론 발현 조건을 정리하시오. [6점]',
 [pt_('포도당 O, 젖당 O일 때 양의 조절은? (성공/실패)',['실패'],1,'포도당 있음 → cAMP 적음 → CAP 불활성'),
  pt_('포도당 O, 젖당 O일 때 음의 조절 해제는? (성공/실패)',['성공'],1,'젖당 → 알로젖당이 억제자 불활성화'),
  pt_('포도당 X, 젖당 X일 때 음의 조절 해제는? (성공/실패)',['실패'],1,'억제자가 작동자에 결합'),
  pt_('오페론이 강하게 발현되는 조건은? (포도당 O/X, 젖당 O/X 형식, 예: 포도당X젖당O)',['포도당X젖당O','포도당X 젖당O','포도당 X 젖당 O','포도당x젖당o'],3,'양의 조절 성공 + 음의 조절 해제')],['b2:1'])
S('b2l06',P,U,3,'[정리 5] 포도당과 젖당이 함께 든 배지에서 대장균 수가 구간 Ⅰ(0~2 h) 증가 → Ⅱ(2~3 h) 정체 → Ⅲ(3~5 h) 다시 증가했다. [6점]',
 [pt_('구간 Ⅰ에서 사용하는 에너지원은?',['포도당','glucose'],1,''),
  pt_('구간 Ⅰ, Ⅱ, Ⅲ에서 LacI(억제자) 양의 관계는? (예: Ⅰ>Ⅱ>Ⅲ, Ⅰ=Ⅱ=Ⅲ)',['Ⅰ=Ⅱ=Ⅲ','I=II=III','1=2=3','동일','같다'],2,'조절 유전자는 항상 발현 → 동일'),
  pe('구간 Ⅱ에서 성장이 정체되는 이유를 쓰시오.',3,['포도당 고갈','cAMP↑ → CAP 활성화, 젖당 분해 효소 합성에 시간 필요','효소가 충분히 만들어진 뒤 Ⅲ에서 젖당 이용'],'포도당이 고갈된 뒤 cAMP 농도가 높아지고 CAP가 활성화되어 젖당 오페론이 발현되기까지 젖당 분해 효소를 합성하는 시간이 필요하기 때문이다(이후 Ⅲ에서 젖당을 이용해 다시 증가).')],['b2:1','b2:8'])
M('b2l07',P,U,2,'[lac 연습 5, 2012 MD예비] 위 구간 Ⅰ, Ⅱ, Ⅲ의 대장균에서 일어나는 현상을 옳게 설명한 것은?',
 [('Ⅰ보다 Ⅲ에서 cAMP 농도가 더 높다','Ⅰ은 포도당 사용 → cAMP 적음, Ⅲ은 포도당 고갈 → 많음'),('lacI 단백질의 농도는 Ⅰ > Ⅱ > Ⅲ 순으로 낮다','항상 발현 → Ⅰ = Ⅱ = Ⅲ'),('cAMP–CAP 복합체가 Ⅱ에서 서로 분리된다','Ⅱ에서 결합(활성화)해요.'),('Ⅰ보다 Ⅱ에서 β-갈락토시데이스의 농도가 더 낮다','Ⅱ에서 더 높아요.')],'CAP 자체의 발현량도 Ⅰ = Ⅱ = Ⅲ (활성만 달라짐)',['b2:6'])
S('b2l08',P,U,3,'[lac 연습 1(1)] 각 유전자형의 β-갈락토시데이스 활성(+/−)을 쓰시오. (Iˢ 아님, I⁻: 억제자 X, Oᶜ: 억제자 결합 X, Z⁻: 효소 활성 X) [6점]',
 [pt_('I⁺Oᶜ Z⁺ — 젖당 있을 때 / 없을 때 (예: +/+)',['+/+','++'],2,'Oᶜ → 억제자 결합 X → 구성적'),
  pt_('I⁻O⁺Z⁻ / I⁺O⁺Z⁺ — 젖당 있을 때 / 없을 때',['+/-','+/−','+-'],2,'I⁺ 억제자가 트랜스로 작용 → 유도성'),
  pt_('I⁺Oᶜ Z⁻ / I⁺O⁺Z⁺ — 젖당 있을 때 / 없을 때',['+/-','+/−','+-'],2,'Oᶜ는 시스로만 작용 → Oᶜ에 연결된 Z⁻는 효소 X, Z⁺는 O⁺에 연결 → 유도성')],['b2:5'])
M('b2l09',P,U,2,'[lac 연습 1(2)] 젖당 유무에 관계없이 오페론이 발현되지 않는 lacI 돌연변이(Iˢ)의 억제자 특성은?',
 [('억제자가 유도체(알로젖당)와 결합하지 못해 항상 작동자에 결합한다','슈퍼 억제자 → 불능'),('억제자가 작동자에 결합하지 못한다','I⁻ 또는 Oᶜ 특징 → 구성적'),('억제자가 만들어지지 않는다','I⁻ → 구성적'),('억제자가 cAMP와 결합한다','관계없어요.')],'Iˢ는 I⁺에 대해서도 우성(트랜스로 작용)',['b2:5'])
E('b2l10',P,U,'[lac 연습 2] 포도당과 젖당이 모두 든 배지에서 야생형은 a구간 증가 → 정체 → b구간 빠른 증가, CAP 결합 부위(활성자 결합 부위)와 lacI 일부가 결실된 돌연변이주는 A 시점 이후 c구간에서 느리게 증가했다. a의 에너지원, A 시점 이후 증가 둔화 이유, b와 c의 생장 속도 차이를 cAMP–CAP과 관련지어 서술하시오. [6점]',
 ['a: 포도당','A: 포도당 고갈','b: cAMP–CAP이 CAP 결합 부위에 결합 → 양의 조절 → 전사 촉진 → 빠른 생장','c: CAP 결합 부위 결실 → 양의 조절 X → 전사 촉진 X → 느린 생장 (lacI 결실로 젖당 오페론은 약하게 구성적 발현)'],
 'a 구간에서는 포도당을 사용한다. A 시점에서 포도당이 고갈된다. 야생형은 포도당이 고갈되면 cAMP–CAP이 CAP 결합 부위에 결합해 젖당 오페론의 전사를 촉진하므로 b 구간에서 빠르게 자라지만, 돌연변이주는 CAP 결합 부위가 없어 양의 조절이 일어나지 않아 전사가 촉진되지 못하므로 c 구간에서 느리게 자란다.',['b2:5'])
M('b2l11',P,U,3,'[lac 연습 6] 대장균 X(I⁻P⁺O⁺Z⁺)와 Y(I⁻P⁺O⁺Z⁺ / I⁺P⁺O⁺Z⁺)를 포도당 최소배지에서 키운 뒤, 젖당 첨가(X→A, Y→C)와 미첨가(X→B, Y→D)로 나누어 15분 배양했다. β-갈락토시데이스 활성 비교로 옳은 것은?',
 [('C > A = B > D','X는 억제자 X → 젖당과 무관하게 구성적(A = B), Y는 유도성이며 Z⁺가 2개 → C 최대, D ≈ 0'),('A > C > B > D','A = B예요.'),('A = B = C = D','Y는 유도성이에요.'),('D > C > A = B','D는 억제돼요.')],'',['b2:6'])
S('b2l12',P,U,3,'[lac 연습 7] F′ 부분 2배체에서 젖당 유무에 따른 z, y 발현량(야생형 젖당 있음 = 1000 기준). 야생형 I⁺O⁺Z⁺Y⁺: 없음 1, 1 / 있음 1000, 1000 · F′ I⁺O⁺Z⁺Y⁻ / I⁻OᶜZ⁻Y⁺: 없음 z 500, y 500 / 있음 1000, 1000. F′ I⁻O⁺Z⁺Y⁺ / I⁺OᶜZ⁺Y⁻의 값을 구하시오. (Oᶜ 오페론은 젖당이 없어도 500 발현) [7점]',
 [pn('젖당 없음, z 발현량 (가)',501,0.5,'',3,'O⁺ 쪽: I⁺ 억제자가 트랜스로 억제 → 1 / Oᶜ 쪽: 500 → 501'),
  pn('젖당 없음, y 발현량 (나)',1,0.01,'',2,'Y⁺는 O⁺ 쪽에만 → 1 (Oᶜ 쪽은 Y⁻)'),
  pn('젖당 있음, z 발현량 (다)',2000,0.5,'',2,'두 오페론 모두 1000씩 → 2000')],['b2:7'])
M('b2l13',P,U,2,'[lac 연습 7] 작동자 돌연변이 Oᶜ의 특성으로 옳은 것은?',
 [('시스로만 작용하여 같은 DNA 위의 구조 유전자만 구성적으로 발현시킨다','억제자는 트랜스, 작동자는 시스'),('트랜스로 작용하여 다른 DNA의 오페론도 구성적으로 만든다','작동자는 DNA 자리라 시스로만 작용해요.'),('억제자를 만들지 못한다','I⁻의 특징이에요.'),('유도체와 결합하지 못한다','Iˢ의 특징이에요.')],'',['b2:7','b2:8'])
S('b2l14',P,U,2,'[lac 연습 8] 포도당, 젖당, 글리세롤, 포도당+젖당을 단일 탄소원으로 하는 최소배지에서 야생형 대장균의 cAMP 농도와 lacZ mRNA 양을 조사했다. [5점]',
 [pt_('젖당 배지에서 cAMP 농도는? (높음/낮음)',['높음','높다'],1,'포도당 없음'),
  pt_('글리세롤 배지에서 lacZ mRNA 양은? (많음/적음)',['적음','적다'],2,'cAMP는 높지만 유도체(젖당) 없음 → 억제자 결합'),
  pt_('lacZ mRNA가 가장 많은 탄소원은?',['젖당','lactose'],2,'포도당 X + 젖당 O')],['b2:7'])
E('b2l15',P,U,'[lac 연습 8-①] cAMP–CAP의 역할을 분자 수준에서 설명하시오. [3점]',
 ['포도당 고갈 → cAMP↑ → CAP에 결합','cAMP–CAP이 프로모터 근처 CAP 결합 부위에 결합','DNA를 구부리고 RNA 중합 효소(α 소단위체 CTD)와 상호작용','→ RNA 중합 효소의 프로모터 결합력 증가 → 전사 촉진'],
 '포도당이 고갈되면 cAMP가 증가해 CAP에 결합하고, cAMP–CAP 복합체는 CAP 결합 부위에 결합하여 DNA를 구부리고 RNA 중합 효소의 α 소단위체 CTD와 상호작용해 RNA 중합 효소가 프로모터에 더 잘 결합하도록 한다.',['b2:7'])
S('b2l16',P,U,3,'[김나리T 유도성/상시성/불능 판정 (전제: 포도당 고갈)] 각 유전자형이 유도성, 상시성(구성적), 불능 중 무엇인지 쓰시오. [8점]',
 [pt_('I⁻O⁺Z⁺',['상시성','상시','구성적'],1,'억제자 X'),
  pt_('F′ I⁻O⁺Z⁺ / I⁺O⁺Z⁺',['유도성','유도'],1,'I⁺가 트랜스로 둘 다 억제'),
  pt_('F′ I⁺OᶜZ⁺ / I⁺O⁺Z⁻',['상시성','상시','구성적'],2,'Oᶜ 쪽 Z⁺가 구성적'),
  pt_('F′ I⁺OᶜZ⁻ / I⁻O⁺Z⁺',['유도성','유도'],2,'Oᶜ 쪽은 Z⁻ → 효소 X / O⁺Z⁺는 I⁺ 억제자로 유도성'),
  pt_('F′ IˢO⁺Z⁺ / I⁺O⁺Z⁺',['불능','유도불능','발현불능'],2,'Iˢ가 우성 → 두 작동자 모두에 항상 결합')],['b2:8'])
M('b2l17',P,U,2,'시간–효소량 그래프에서 t₁에 유도체를 넣었을 때 A(처음부터 높게 계속 증가), B(t₁ 이후 증가), C(변화 없이 낮음)로 나타났다. 각각을 바르게 짝지은 것은?',
 [('A – 상시성, B – 유도성, C – 불능','t₁에 반응하는 것이 유도성이에요.'),('A – 유도성, B – 상시성, C – 불능','상시성은 유도체와 관계없이 증가해요.'),('A – 불능, B – 유도성, C – 상시성','불능은 발현이 없어요.'),('A – 상시성, B – 불능, C – 유도성','유도성은 t₁ 이후 증가해요.')],'',['b2:8'])
S('b2l18',P,U,3,'[심화 3·4] 젖당 오페론에는 주작동자 O₁과 보조작동자 O₂(+412), O₃(−82)가 있다. 작동자 조합별 억제 배수: O₁ 약 18배, O₂ 또는 O₃만 거의 없음, O₁+O₂ 약 700배, O₁+O₃ 약 440배, O₁+O₂+O₃ 약 1300배. [7점]',
 [pn('O₃를 결실시키면 억제 능력은 약 몇 배 감소하는가? (정수)',2,0.2,'배',2,'O₁+O₂ = 700 → 1300 / 700 ≈ 1.9 ≈ 2배 (논술 제시문: 약 2배)'),
  pn('O₂와 O₃를 동시에 결실시키면 약 몇 배 감소하는가? (정수)',72,3,'배',2,'1300 / 18 ≈ 72 (논술 제시문: 약 70배)'),
  pe('보조작동자의 역할을 쓰시오.',3,['억제자는 사량체 → 두 작동자에 동시에 결합','DNA 고리(루프) 형성','주작동자 근처 억제자 농도↑ → 전사를 훨씬 효과적으로 억제'],'사량체 억제자가 주작동자와 보조작동자에 동시에 결합해 DNA 고리를 만들어 주작동자에 결합할 확률을 높이므로 전사를 훨씬 효과적으로 억제한다(보조작동자만으로는 억제가 거의 없음).')],['b2:1','b2:8','b2:9'])
M('b2l19',P,U,3,'억제자 농도에 따른 오퍼레이터 결합률 그래프에서 O⁺(정상)는 낮은 억제자 농도에서도 빠르게 결합률이 100 %에 가까워지고, Oᶜ는 Kd가 훨씬 커서 천천히 증가한다. 옳은 해석은?',
 [('Oᶜ는 억제자가 적을 때는 억제가 극복되지 않지만(구성적), 억제자가 매우 많아지면 결합되어 억제될 수 있다','Kd(Oᶜ) > Kd(O⁺)'),('Oᶜ는 억제자와 전혀 결합하지 못한다','O 결손(작동자 없음)의 경우예요.'),('Kd가 클수록 결합력이 크다','Kd가 클수록 결합력이 작아요.'),('O⁺와 Oᶜ의 Kd는 같다','Oᶜ가 훨씬 커요.')],'학습지 표현: Oᶜ는 억제자가 적을 때 억제 극복 X, 많을 때 극복 (주작동자 없는 경우와 다름)',['b2:1','b2:8'])
E('b2l20',P,U,'[논술 문제 2-iii] 억제단백질은 2개 또는 4개의 단백질이 결합해 사량체를 이루고, 작동자 DNA에 결합하며, 알로젖당과 결합하면 작동자에 결합하지 못한다. 단백질이 여러 독립적 기능 부위(도메인)로 이루어진다고 할 때, 젖당 오페론 억제단백질의 도메인을 기능에 따라 설명하시오. [3점]',
 ['DNA(작동자) 결합 도메인','유도체(알로젖당) 결합 도메인','소단위체끼리 결합하는 도메인(사량체 형성)'],
 '억제단백질은 ① 작동자 DNA에 결합하는 DNA 결합 도메인, ② 알로젖당과 결합해 구조를 바꾸는 유도체 결합 도메인, ③ 다른 억제단백질 소단위체와 결합해 사량체를 이루는 도메인으로 구성된다.',['b2:9'])
E('b2l21',P,U,'[논술 문제 2-i] 작동자2와 작동자3에 억제단백질이 결합하지 못하게 DNA 염기서열을 돌연변이시켰더니 억제 능력이 현저히 감소하였다. 억제단백질은 작동자2, 3에 결합할 수 있으나 RNA 중합효소의 프로모터 결합을 직접 방해하지는 않는다. 이 결과를 설명하시오. [3점]',
 ['억제자 사량체가 O₁과 O₂/O₃에 동시 결합 → DNA 고리','고리 형성으로 O₁ 결합 안정화·국소 농도 증가','O₂·O₃ 돌연변이 → 고리 X → O₁ 결합 확률↓ → 억제 능력 감소'],
 '사량체 억제단백질은 작동자1과 작동자2 또는 3에 동시에 결합해 DNA 고리를 만들며, 이로써 작동자1에 결합한 상태가 안정되고 주변 농도가 높아진다. 작동자2·3에 결합하지 못하면 고리가 형성되지 않아 작동자1에 결합하는 확률이 낮아지므로 억제 능력이 크게 감소한다.',['b2:9'])
# ================= 진핵생물 유전자 발현 조절 =================
U='진핵생물 발현 조절'
M('b2e01',P,U,1,'진핵생물의 유전자 발현 조절 단계를 순서대로 나열한 것은?',
 [('염색질 구조 → 전사 → RNA 가공 → mRNA 수송·분해 → 번역 → 번역 후(단백질 가공·분해)','여러 단계에서 조절돼요.'),('번역 → 전사 → RNA 가공 → 염색질 구조','순서가 틀려요.'),('전사 → 염색질 구조 → 번역 → RNA 가공','RNA 가공은 번역 전이에요.'),('진핵생물은 전사 단계에서만 조절된다','여러 단계예요.')],'',['b2:10','b2:11','b2:12'])
M('b2e02',P,U,2,'다세포 진핵생물에서 세포마다 발현되는 유전자가 다른 이유로 옳은 것은?',
 [('모든 세포가 같은 유전체를 가지지만 세포마다 발현되는 유전자 조합이 다르기 때문','예: 간세포는 알부민, 수정체 세포는 크리스탈린'),('세포마다 서로 다른 유전체를 가지기 때문','유전체는 같아요(유전체 동등성).'),('분화하면서 필요 없는 유전자를 제거하기 때문','유전자를 잃지 않아요(핵 이식 실험).'),('간세포에는 크리스탈린 유전자가 없기 때문','유전자는 있지만 발현되지 않아요.')],'',['b2:10','b2:13'])
M('b2e03',P,U,2,'히스톤 아세틸화가 전사를 촉진하는 원리로 옳은 것은?',
 [('히스톤 꼬리의 라이신에 아세틸기가 붙어 양전하가 중화되면 DNA(음전하)와의 결합이 약해져 염색질이 느슨해진다','RNA 중합 효소·전사 인자가 접근하기 쉬워져요.'),('아세틸기가 DNA 염기를 바꾸기 때문','DNA 서열은 그대로예요.'),('히스톤이 DNA를 더 단단히 감기 때문','탈아세틸화의 결과예요.'),('아세틸화된 히스톤이 RNA 중합 효소로 작용하기 때문','관계없어요.')],'탈아세틸화 → 응축 → 전사 억제',['b2:10'])
M('b2e04',P,U,3,'히스톤 메틸화에 대한 설명으로 옳은 것은?',
 [('H3K9 메틸화(H3K9me3)는 HP1이 결합하여 이질염색질을 형성하므로 전사를 억제한다','어떤 라이신이 메틸화되는지에 따라 효과가 달라요.'),('히스톤 메틸화는 항상 전사를 촉진한다','H3K4me3는 촉진, H3K9me3는 억제예요.'),('히스톤 메틸화는 DNA 메틸화와 같은 말이다','대상이 달라요(단백질 vs 시토신).'),('메틸화는 라이신의 양전하를 중화한다','메틸화는 전하를 중화하지 않아요(아세틸화가 중화).')],'',['b2:10'])
T('b2e05',P,U,1,'DNA 메틸화가 주로 일어나는 염기와, 프로모터에 C–G가 반복되어 많이 존재하는 부위의 이름을 쓰시오. (예: 아데닌, ○○ 섬)',['시토신, CpG 섬','시토신 CpG섬','시토신,CpG섬','시토신, CpG island','사이토신, CpG 섬','시토신 CpG 섬'],'DNMT가 SAM의 메틸기를 시토신 5번 탄소에 붙여 5-메틸시토신 형성 → 프로모터 메틸화 → 전사 억제',['b2:11'])
B('b2e06',P,U,3,'DNA 메틸화에 대한 설명으로 옳은 것만을 <보기>에서 있는 대로 고른 것은?',
 [['프로모터의 CpG 섬이 메틸화되면 전사 인자 결합이 방해되어 유전자 발현이 억제된다.',True,'메틸화 DNA 결합 단백질이 히스톤 탈아세틸화도 유도해요.'],
  ['DNA 복제 후 반메틸화된 DNA를 DNMT1이 인식해 새 가닥을 메틸화하므로 메틸화 양상이 딸세포로 유전된다.',True,'유지 메틸화'],
  ['DNA 메틸화는 염기 서열을 바꾸므로 돌연변이의 한 종류이다.',False,'염기 서열은 그대로인 후성유전적 변화예요.']],['b2:11'])
M('b2e07',P,U,2,'포유류 암컷에서 X 염색체 하나가 불활성화되는 과정에 대한 설명으로 옳은 것은?',
 [('불활성화될 X에서 Xist lncRNA가 전사되어 그 X 염색체를 뒤덮고, DNA 메틸화·히스톤 탈아세틸화가 일어나 응축(바소체)된다','Xist는 자신이 전사된 X에 시스로 작용해요.'),('Xist는 단백질로 번역되어 X를 분해한다','번역되지 않는 lncRNA예요.'),('활성 X에서도 Xist가 많이 발현된다','활성 X는 Tsix가 Xist를 억제해요.'),('X 불활성화는 수컷에서만 일어난다','암컷(XX)에서 일어나요.')],'',['b2:11'])
M('b2e08',P,U,2,'진핵생물의 전사 개시 조절에 대한 설명으로 옳은 것은?',
 [('특이 전사 인자(활성자)가 인핸서에 결합하면 DNA가 휘어져 매개 단백질을 통해 프로모터의 일반 전사 인자·RNA 중합 효소와 상호작용한다','멀리 떨어진 인핸서도 작용해요.'),('진핵생물은 RNA 중합 효소 단독으로 프로모터에 결합한다','일반 전사 인자가 필요해요.'),('인핸서는 반드시 프로모터 바로 옆에 있다','수천 bp 떨어져도 돼요.'),('하나의 유전자는 하나의 전사 인자로만 조절된다','여러 조절 요소의 조합(조합적 조절)이에요.')],'',['b2:10'])
M('b2e09',P,U,2,'선택적 RNA 스플라이싱에 대한 설명으로 옳은 것은?',
 [('하나의 1차 전사체에서 서로 다른 엑손 조합의 mRNA를 만들어 여러 종류의 단백질을 생산한다','예: 트로포닌 T 유전자'),('인트론을 남겨 두어 단백질을 길게 만든다','엑손 선택이 달라지는 거예요.'),('원핵생물에서 주로 일어난다','진핵생물의 RNA 가공이에요.'),('리보솜이 스플라이싱을 수행한다','snRNA와 단백질로 이루어진 스플라이소솜이 해요.')],'',['b2:11'])
T('b2e10',P,U,1,'RNA 스플라이싱을 수행하는, snRNA와 단백질로 이루어진 복합체는?',['스플라이소솜','스플라이스솜','스플라이싱 복합체','spliceosome','스플라이소좀'],'스플라이소솜 = snRNA(small nuclear RNA) + 단백질 → 스플라이싱 부위(GU…AG) 인식',['b2:11'])
M('b2e11',P,U,2,'mRNA 수준의 발현 조절에 대한 설명으로 옳지 않은 것은?',
 [('poly A 꼬리가 짧을수록 mRNA 수명이 길어진다','길수록 수명이 길어져요(옳지 않음).'),('5′ 캡과 poly A 꼬리는 mRNA를 분해 효소로부터 보호한다','옳아요.'),('5′ UTR에 조절 단백질이 결합하면 리보솜 결합이 막혀 번역이 억제될 수 있다','번역 개시 조절'),('mRNA의 수명이 길수록 더 많은 단백질이 만들어진다','옳아요.')],'',['b2:11','b2:12'])
M('b2e12',P,U,2,'miRNA와 siRNA를 비교한 설명으로 옳은 것은?',
 [('miRNA는 표적 mRNA와 부분적으로 상보적이면 주로 번역을 억제하고, siRNA는 완전히 상보적으로 결합해 mRNA를 분해한다','miRNA: 세포 스스로 만든 것, siRNA: 외래(바이러스 등) 이중 가닥 RNA 유래'),('miRNA는 단백질을 분해한다','mRNA를 조절해요.'),('siRNA는 Dicer 없이 만들어진다','둘 다 Dicer가 자르고 Argonaute와 결합해요.'),('miRNA는 DNA를 메틸화하는 효소이다','작은 RNA예요.')],'',['b2:12'])
M('b2e13',P,U,3,'miRNA의 생성 과정을 순서대로 바르게 나열한 것은?',
 [('miRNA 유전자 전사(pri-miRNA) → 핵에서 Drosha가 절단(pre-miRNA) → Exportin-5로 세포질 이동 → Dicer가 절단 → 한 가닥이 Argonaute와 복합체 형성','핵 → 세포질'),('Dicer 절단 → Drosha 절단 → 전사 → 핵 이동','순서가 반대예요.'),('세포질에서 전사 → Argonaute → Drosha','전사는 핵에서 일어나요.'),('pre-miRNA → pri-miRNA → miRNA','pri가 먼저예요.')],'',['b2:12'])
M('b2e14',P,U,2,'신호 인식 입자(SRP)의 역할로 옳은 것은?',
 [('신호 펩티드가 번역되어 나오면 결합해 번역을 일시 정지시키고 리보솜을 소포체(ER)로 데려간다','이후 ER 안으로 번역되며 들어가 분비·막단백질이 돼요.'),('mRNA의 스플라이싱을 수행한다','스플라이스솜의 역할이에요.'),('단백질에 유비퀴틴을 붙인다','유비퀴틴 연결 효소의 역할이에요.'),('전사 종결을 일으킨다','관계없어요.')],'',['b2:12'])
M('b2e15',P,U,2,'번역 후 조절에 대한 설명으로 옳은 것은?',
 [('프로인슐린에서 C-펩티드가 잘려 나가야 활성 인슐린이 되며, 유비퀴틴이 붙은 단백질은 프로테아솜에서 분해된다','번역 후 가공 + 선택적 분해'),('인슐린은 번역 직후 바로 활성형이다','가공이 필요해요.'),('프로테아솜은 mRNA를 분해한다','단백질을 분해해요.'),('유비퀴틴은 단백질을 안정화한다','분해 표지예요.')],'',['b2:12'])
E('b2e16',P,U,'진핵세포에서 같은 유전자라도 염색질 상태에 따라 발현 여부가 달라진다. 진정염색질과 이질염색질의 차이를 히스톤 변형과 DNA 메틸화로 설명하시오. [4점]',
 ['진정염색질: 느슨, 히스톤 아세틸화(H3K4me3 등), 전사 활발','이질염색질: 응축, 탈아세틸화·H3K9me3·HP1, 전사 억제','DNA(CpG) 메틸화 → 메틸화 결합 단백질 → 탈아세틸화 유도 → 응축','→ 전사 인자·RNA 중합 효소 접근성 차이'],
 '진정염색질은 히스톤이 아세틸화되어 느슨하므로 전사 인자와 RNA 중합 효소가 접근해 전사가 활발하다. 이질염색질은 히스톤이 탈아세틸화되고 H3K9 메틸화에 HP1이 결합해 응축되어 있으며, 프로모터 DNA 메틸화도 응축을 촉진하므로 전사가 억제된다.',['b2:10','b2:11'])
E('b2e17',P,U,'일란성 쌍둥이는 유전체가 같지만 나이가 들수록 질병 감수성 등의 차이가 커진다. 그 원인을 후성유전학적 관점에서 설명하시오. [3점]',
 ['DNA 서열은 같음','환경·생활 습관에 따라 DNA 메틸화·히스톤 변형 양상이 달라짐','유전자 발현 차이 → 표현형 차이 (나이가 들수록 누적)'],
 '쌍둥이는 염기 서열이 같지만 서로 다른 환경과 생활 습관 속에서 DNA 메틸화와 히스톤 변형 양상이 달라지고, 이러한 후성유전적 차이가 쌓이면서 유전자 발현이 달라져 표현형 차이가 커진다.',['b2:11'])
U='세포 분화·발생'
M('b2d01',P,U,2,'MyoD에 대한 설명으로 옳은 것은?',
 [('근육 세포 분화를 결정하는 주조절 유전자의 산물로, 자기 유전자의 전사도 촉진(양성 피드백)하고 다른 근육 특이 유전자의 전사를 활성화한다','결정 → 분화'),('모든 세포에서 같은 양으로 발현된다','근육 전구 세포에서 발현돼요.'),('MyoD는 근육 수축 단백질(액틴)이다','전사 인자예요.'),('MyoD가 발현되면 세포 분열이 계속 촉진된다','분화하며 분열을 멈춰요.')],'',['b2:13'])
M('b2d02',P,U,2,'혹스(Hox) 유전자에 대한 설명으로 옳은 것은?',
 [('몸의 전후축을 따라 각 체절에 어떤 구조가 생길지 결정하며, 염색체 위 배열 순서와 몸에서 발현되는 순서가 같다','공선성'),('혹스 유전자가 돌연변이되어도 형태는 변하지 않는다','Antp 돌연변이 → 더듬이 자리에 다리'),('혹스 유전자는 식물에만 있다','동물 발생의 주조절 유전자예요.'),('혹스 유전자는 효소 단백질을 암호화한다','전사 인자(호메오도메인)를 암호화해요.')],'',['b2:13'])
M('b2d03',P,U,2,'초파리에서 Antp 유전자가 머리에서도 발현되는 돌연변이가 일어났을 때 나타나는 현상은?',
 [('더듬이 자리에 다리가 생긴다','Antp는 가슴(다리) 체절을 지정해요.'),('날개가 2쌍이 된다','Ubx 기능 상실의 결과예요.'),('눈이 사라진다','관계없어요.'),('몸 전체가 머리가 된다','특정 체절만 바뀌어요.')],'',['b2:13'])
S('b2d04',P,U,3,'[ABC 모델] 꽃은 바깥쪽부터 1층 꽃받침, 2층 꽃잎, 3층 수술, 4층 암술로 이루어진다. A 유전자는 1·2층, B는 2·3층, C는 3·4층에서 발현되고, A와 C는 서로 억제한다. [7점]',
 [pt_('꽃잎을 만드는 유전자 조합은?',['A+B','AB','A, B','A,B','B+A'],1,''),
  pt_('수술을 만드는 유전자 조합은?',['B+C','BC','B, C','B,C','C+B'],1,'수술 = B + C (꽃잎 A + B와 헷갈리지 않기)'),
  pt_('B 유전자 기능 상실 돌연변이의 꽃 구조를 바깥쪽부터 쓰시오. (예: 꽃받침-꽃잎-수술-암술)',['꽃받침-꽃받침-암술-암술','꽃받침 꽃받침 암술 암술'],2,'A, A, C, C'),
  pt_('A 유전자 기능 상실 돌연변이의 꽃 구조를 바깥쪽부터 쓰시오.',['암술-수술-수술-암술','암술 수술 수술 암술'],3,'A 없음 → C가 1·2층까지 확장: C, B+C, B+C, C')],['b2:13'])
E('b2d05',P,U,'분화된 세포의 핵을 핵을 제거한 난자에 이식하면 완전한 개체가 발생할 수 있다. 이 사실로부터 알 수 있는 것과, 그럼에도 세포마다 형태와 기능이 다른 이유를 쓰시오. [4점]',
 ['분화된 세포도 개체 발생에 필요한 모든 유전자를 가짐(유전체 동등성)','분화 과정에서 유전자를 잃지 않음','세포마다 발현되는 유전자 조합이 다름(선택적 발현)','후성유전적 상태·전사 인자 조합 차이'],
 '분화된 세포의 핵에도 개체 발생에 필요한 모든 유전 정보가 있음을 알 수 있다. 세포마다 형태와 기능이 다른 것은 유전자를 잃어서가 아니라 세포마다 전사 인자 조합과 염색질 상태가 달라 발현되는 유전자가 다르기 때문이다.',['b2:13'])
U='유전공학'
M('b2g01',P,U,3,'노던 블롯 전 RNA 품질을 확인하기 위해 전기 영동했을 때, 분해되지 않은 정상 RNA의 특징은?',
 [('28S와 18S rRNA 띠가 선명하고 28S가 18S보다 약 2배 진하다','RNA의 대부분은 rRNA예요.'),('띠 없이 아래로 길게 번진 모양(스미어)이다','분해된 RNA의 특징이에요.'),('mRNA 띠만 하나 선명하게 보인다','mRNA는 크기가 다양해 번져 보여요.'),('18S가 28S보다 진하다','28S가 약 2배 진해요.')],'',['b2:16'])
